UPDATE posts
SET view_count = COALESCE(view_count, 0) + 1
WHERE id = #{id}

UPDATE posts
SET like_count = GREATEST(0, COALESCE(like_count, 0) + #{delta})
WHERE id = #{id}

UPDATE posts
SET favorite_count = GREATEST(0, COALESCE(favorite_count, 0) + #{delta})
WHERE id = #{id}

